#include <iostream>
using namespace std;
{{BLANK}}
class Mage : public Hero {
private:
    int magic_mult;
public:
    Mage(int dmg, int mult) : Hero(dmg), magic_mult(mult) {}
    void attack() const override {
        cout << "Mage casts spell for " << base_damage * magic_mult << " damage!" << endl;
    }
};

int main() {
    Hero* heroes[2];

    // Warrior构造函数参数：(基础伤害, 武器加成)
    heroes[0] = new Warrior(10, 5);

    // Mage构造函数参数：(基础伤害, 魔法倍率)
    heroes[1] = new Mage(10, 3);

    for (int i = 0; i < 2; ++i) {
        heroes[i]->attack();
        delete heroes[i]; // 确保不会发生内存泄漏
    }
    return 0;
}

