class Hero {
protected:
    int base_damage;
public:
    Hero(int dmg) : base_damage(dmg) {}
    virtual void attack() const = 0;
    virtual ~Hero() {}
};
class Warrior : public Hero {
private:
    int weapon_bonus;
public:
    Warrior(int dmg, int bonus) : Hero(dmg), weapon_bonus(bonus) {}
    void attack() const override {
        cout << "Warrior attacks for " << base_damage + weapon_bonus << " damage!" << endl;
    }
};
